function maskToBase64(mask){let bin='';const ch=0x8000;for(let i=0;i<mask.length;i+=ch)bin+=String.fromCharCode.apply(null,mask.subarray(i,Math.min(i+ch,mask.length)));return btoa(bin);}
function base64ToMask(b64,len){const bin=atob(b64);const m=new Uint8Array(len);for(let i=0;i<Math.min(bin.length,len);i++)m[i]=bin.charCodeAt(i);return m;}
function persistAnnotations(){try{const p={masks:{},polygons:{},sources:{},savedAt:Date.now()};for(const[k,mask]of manualMasks)p.masks[k]={data:maskToBase64(mask),length:mask.length};for(const[k,polys]of savedPolygons)p.polygons[k]=polys;for(const[k,s]of annotationSource)p.sources[k]=s;localStorage.setItem(ANNOTATION_STORAGE_KEY,JSON.stringify(p));}catch(e){console.warn(e);}}
function loadAnnotationsFromStorage(){try{const raw=localStorage.getItem(ANNOTATION_STORAGE_KEY);if(!raw)return;const p=JSON.parse(raw);if(p.masks)for(const[k,o]of Object.entries(p.masks))if(o&&o.data&&o.length)manualMasks.set(k,base64ToMask(o.data,o.length));if(p.polygons)for(const[k,polys]of Object.entries(p.polygons))savedPolygons.set(k,polys);if(p.sources)for(const[k,s]of Object.entries(p.sources))annotationSource.set(k,s);}catch(e){console.warn(e);}}
function pushAnnotationUndo(){const key=getActiveImageKey();if(!key||!manualMasks.has(key))return;annotationUndoStack.push({key,maskCopy:new Uint8Array(manualMasks.get(key))});if(annotationUndoStack.length>MAX_UNDO)annotationUndoStack.shift();}
function undoAnnotation(){if(!annotationUndoStack.length){alert(typeof currentLang!=='undefined'&&currentLang==='he'?'אין פעולות לביטול':'Nothing to undo');return;}const last=annotationUndoStack.pop();manualMasks.set(last.key,last.maskCopy);annotationSource.set(last.key,'manual');persistAnnotations();renderPreview(true);}
